//-----------------------------------------------------------
// Description: This module stores ordered semantic coding-tree
// syntax events generated by the VVC partition engine. The FIFO
// preserves DFS event order and intentionally does not store NODE_ID.
// Each entry carries CTU identification, node geometry/depth,
// legal split mask, selected split type, leaf indication, and CU_ID.
// Both write and read sides use ready/valid flow control. The payload
// memory is not reset so FPGA block-RAM inference is preserved.
//-----------------------------------------------------------

`timescale 1ns/1ps

module PARTITION_SYNTAX_FIFO
#(
  parameter PARA_CTU_ID_WD = 9,
  parameter PARA_CU_ID_WD  = 8,
  parameter PARA_DEPTH     = 256,

  localparam PARA_DATA_WD =
    PARA_CTU_ID_WD + 5 + 5 + 3 + 3 + 3 + 3 + 2 + 6 + 3 + 1 +
    PARA_CU_ID_WD,

  localparam PARA_ADDR_WD =
    (PARA_DEPTH <= 1) ? 1 : $clog2(PARA_DEPTH),

  localparam PARA_COUNT_WD =
    (PARA_DEPTH < 1) ? 1 : $clog2(PARA_DEPTH + 1)
)
(
  input                              I_CLK,
  input                              I_RESETN,
  input                              I_CLEAR,

  input                              I_WR_VALID,
  output logic                       O_WR_READY,

  input      [PARA_CTU_ID_WD-1:0]    I_CTU_ID,
  input      [4:0]                   I_X_UNIT,
  input      [4:0]                   I_Y_UNIT,
  input      [2:0]                   I_WIDTH_CODE,
  input      [2:0]                   I_HEIGHT_CODE,
  input      [2:0]                   I_QT_DEPTH,
  input      [2:0]                   I_MTT_DEPTH,
  input      [1:0]                   I_PART_IDX,
  input      [5:0]                   I_LEGAL_MASK,
  input      [2:0]                   I_SPLIT_TYPE,
  input                              I_IS_LEAF,
  input      [PARA_CU_ID_WD-1:0]     I_CU_ID,

  output logic                       O_RD_VALID,
  input                              I_RD_READY,

  output logic [PARA_CTU_ID_WD-1:0]  O_CTU_ID,
  output logic [4:0]                 O_X_UNIT,
  output logic [4:0]                 O_Y_UNIT,
  output logic [2:0]                 O_WIDTH_CODE,
  output logic [2:0]                 O_HEIGHT_CODE,
  output logic [2:0]                 O_QT_DEPTH,
  output logic [2:0]                 O_MTT_DEPTH,
  output logic [1:0]                 O_PART_IDX,
  output logic [5:0]                 O_LEGAL_MASK,
  output logic [2:0]                 O_SPLIT_TYPE,
  output logic                       O_IS_LEAF,
  output logic [PARA_CU_ID_WD-1:0]   O_CU_ID,

  output logic                       O_EMPTY,
  output logic                       O_FULL,
  output logic [PARA_COUNT_WD-1:0]   O_COUNT
);

(* ram_style = "block" *)
logic [PARA_DATA_WD-1:0] r_memory [0:PARA_DEPTH-1];

logic [PARA_ADDR_WD-1:0]  r_write_pointer;
logic [PARA_ADDR_WD-1:0]  r_read_pointer;
logic [PARA_COUNT_WD-1:0] r_total_count;

logic [PARA_DATA_WD-1:0]  r_output_data;
logic                     r_output_valid;

logic [PARA_DATA_WD-1:0]  w_input_data;

logic                     w_write_accept;
logic                     w_read_accept;
logic                     w_output_slot_available;

logic [PARA_COUNT_WD-1:0] w_memory_item_count;
logic                     w_memory_has_data;

logic                     w_bypass_write;
logic                     w_memory_write;
logic                     w_memory_read;

// Syntax-event payload layout from MSB to LSB:
//
// CTU_ID
// X_UNIT
// Y_UNIT
// WIDTH_CODE
// HEIGHT_CODE
// QT_DEPTH
// MTT_DEPTH
// PART_IDX
// LEGAL_MASK
// SPLIT_TYPE
// IS_LEAF
// CU_ID
//
// NODE_ID is intentionally absent. FIFO ordering preserves the
// coding-tree DFS event sequence.
assign w_input_data = {
  I_CTU_ID,
  I_X_UNIT,
  I_Y_UNIT,
  I_WIDTH_CODE,
  I_HEIGHT_CODE,
  I_QT_DEPTH,
  I_MTT_DEPTH,
  I_PART_IDX,
  I_LEGAL_MASK,
  I_SPLIT_TYPE,
  I_IS_LEAF,
  I_CU_ID
};

// A write is accepted whenever the FIFO has capacity. If the FIFO
// is currently full but the output entry is consumed in this cycle,
// a new syntax event can still be accepted without a throughput gap.
assign O_WR_READY =
  (r_total_count < PARA_COUNT_WD'(PARA_DEPTH)) ||
  (r_output_valid && I_RD_READY);

assign w_write_accept =
  I_WR_VALID &&
  O_WR_READY;

assign w_read_accept =
  r_output_valid &&
  I_RD_READY;

// The registered output stage may be loaded whenever it is empty or
// whenever the current event is consumed in the same cycle.
assign w_output_slot_available =
  !r_output_valid ||
  w_read_accept;

// r_total_count includes an event already held in the output
// register. Subtract that entry to obtain the number still in RAM.
always_comb begin
  w_memory_item_count = r_total_count;

  if (r_output_valid)
    w_memory_item_count =
      r_total_count - PARA_COUNT_WD'(1);
end

assign w_memory_has_data =
  (w_memory_item_count != PARA_COUNT_WD'(0));

// If no older event is resident in RAM, a newly accepted event may
// bypass the memory and enter the output register directly.
assign w_bypass_write =
  w_output_slot_available &&
  !w_memory_has_data &&
  w_write_accept;

// When an older RAM event exists, it always has priority over a
// new input event and is prefetched into the output register.
assign w_memory_read =
  w_output_slot_available &&
  w_memory_has_data;

// Accepted events are written into RAM unless they take the direct
// bypass path.
assign w_memory_write =
  w_write_accept &&
  !w_bypass_write;

// Payload memory write. The RAM array is intentionally not reset;
// pointer/count state determines which locations contain valid data.
always_ff @ (posedge I_CLK) begin
  if (w_memory_write)
    r_memory[r_write_pointer] <= w_input_data;
end

// Registered output payload. An older RAM event takes priority over
// a simultaneous newly accepted event so FIFO ordering is preserved.
always_ff @ (posedge I_CLK) begin
  if (w_memory_read)
    r_output_data <= r_memory[r_read_pointer];
  else if (w_bypass_write)
    r_output_data <= w_input_data;
end

// Output-valid control. During downstream backpressure neither the
// valid bit nor the output payload changes.
always_ff @ (posedge I_CLK, negedge I_RESETN) begin
  if (!I_RESETN)
    r_output_valid <= 1'b0;
  else if (I_CLEAR)
    r_output_valid <= 1'b0;
  else if (w_output_slot_available) begin
    if (w_memory_read || w_bypass_write)
      r_output_valid <= 1'b1;
    else
      r_output_valid <= 1'b0;
  end
end

// Write pointer advances only when an event is physically stored in
// RAM. Explicit terminal handling supports non-power-of-two depths.
always_ff @ (posedge I_CLK, negedge I_RESETN) begin
  if (!I_RESETN)
    r_write_pointer <= '0;
  else if (I_CLEAR)
    r_write_pointer <= '0;
  else if (w_memory_write) begin
    if (r_write_pointer == PARA_ADDR_WD'(PARA_DEPTH - 1))
      r_write_pointer <= '0;
    else
      r_write_pointer <=
        r_write_pointer + PARA_ADDR_WD'(1);
  end
end

// Read pointer advances when the oldest RAM event is prefetched into
// the registered output stage.
always_ff @ (posedge I_CLK, negedge I_RESETN) begin
  if (!I_RESETN)
    r_read_pointer <= '0;
  else if (I_CLEAR)
    r_read_pointer <= '0;
  else if (w_memory_read) begin
    if (r_read_pointer == PARA_ADDR_WD'(PARA_DEPTH - 1))
      r_read_pointer <= '0;
    else
      r_read_pointer <=
        r_read_pointer + PARA_ADDR_WD'(1);
  end
end

// Occupancy counts events visible in the output register plus events
// still resident in RAM. Simultaneous external read/write transfers
// leave occupancy unchanged.
always_ff @ (posedge I_CLK, negedge I_RESETN) begin
  if (!I_RESETN)
    r_total_count <= '0;
  else if (I_CLEAR)
    r_total_count <= '0;
  else begin
    unique casez ({w_write_accept, w_read_accept})
      2'b10: begin
        r_total_count <=
          r_total_count + PARA_COUNT_WD'(1);
      end

      2'b01: begin
        r_total_count <=
          r_total_count - PARA_COUNT_WD'(1);
      end

      default: begin
      end
    endcase
  end
end

assign O_RD_VALID = r_output_valid;

// Output unpacking mirrors the write-side concatenation.
localparam PARA_CU_ID_LSB      = 0;
localparam PARA_CU_ID_MSB      =
  PARA_CU_ID_LSB + PARA_CU_ID_WD - 1;

localparam PARA_IS_LEAF_LSB    =
  PARA_CU_ID_MSB + 1;
localparam PARA_IS_LEAF_MSB    =
  PARA_IS_LEAF_LSB;

localparam PARA_SPLIT_LSB      =
  PARA_IS_LEAF_MSB + 1;
localparam PARA_SPLIT_MSB      =
  PARA_SPLIT_LSB + 3 - 1;

localparam PARA_LEGAL_LSB      =
  PARA_SPLIT_MSB + 1;
localparam PARA_LEGAL_MSB      =
  PARA_LEGAL_LSB + 6 - 1;

localparam PARA_PART_IDX_LSB   =
  PARA_LEGAL_MSB + 1;
localparam PARA_PART_IDX_MSB   =
  PARA_PART_IDX_LSB + 2 - 1;

localparam PARA_MTT_DEPTH_LSB  =
  PARA_PART_IDX_MSB + 1;
localparam PARA_MTT_DEPTH_MSB  =
  PARA_MTT_DEPTH_LSB + 3 - 1;

localparam PARA_QT_DEPTH_LSB   =
  PARA_MTT_DEPTH_MSB + 1;
localparam PARA_QT_DEPTH_MSB   =
  PARA_QT_DEPTH_LSB + 3 - 1;

localparam PARA_HEIGHT_CODE_LSB =
  PARA_QT_DEPTH_MSB + 1;
localparam PARA_HEIGHT_CODE_MSB =
  PARA_HEIGHT_CODE_LSB + 3 - 1;

localparam PARA_WIDTH_CODE_LSB =
  PARA_HEIGHT_CODE_MSB + 1;
localparam PARA_WIDTH_CODE_MSB =
  PARA_WIDTH_CODE_LSB + 3 - 1;

localparam PARA_Y_UNIT_LSB     =
  PARA_WIDTH_CODE_MSB + 1;
localparam PARA_Y_UNIT_MSB     =
  PARA_Y_UNIT_LSB + 5 - 1;

localparam PARA_X_UNIT_LSB     =
  PARA_Y_UNIT_MSB + 1;
localparam PARA_X_UNIT_MSB     =
  PARA_X_UNIT_LSB + 5 - 1;

localparam PARA_CTU_ID_LSB     =
  PARA_X_UNIT_MSB + 1;
localparam PARA_CTU_ID_MSB     =
  PARA_CTU_ID_LSB + PARA_CTU_ID_WD - 1;

assign O_IS_LEAF =
  r_output_data[PARA_IS_LEAF_MSB:PARA_IS_LEAF_LSB];

assign O_SPLIT_TYPE =
  r_output_data[PARA_SPLIT_MSB:PARA_SPLIT_LSB];

assign O_LEGAL_MASK =
  r_output_data[PARA_LEGAL_MSB:PARA_LEGAL_LSB];

assign O_PART_IDX =
  r_output_data[PARA_PART_IDX_MSB:PARA_PART_IDX_LSB];

assign O_MTT_DEPTH =
  r_output_data[PARA_MTT_DEPTH_MSB:PARA_MTT_DEPTH_LSB];

assign O_QT_DEPTH =
  r_output_data[PARA_QT_DEPTH_MSB:PARA_QT_DEPTH_LSB];

assign O_HEIGHT_CODE =
  r_output_data[PARA_HEIGHT_CODE_MSB:PARA_HEIGHT_CODE_LSB];

assign O_WIDTH_CODE =
  r_output_data[PARA_WIDTH_CODE_MSB:PARA_WIDTH_CODE_LSB];

assign O_Y_UNIT =
  r_output_data[PARA_Y_UNIT_MSB:PARA_Y_UNIT_LSB];

assign O_X_UNIT =
  r_output_data[PARA_X_UNIT_MSB:PARA_X_UNIT_LSB];

assign O_CTU_ID =
  r_output_data[PARA_CTU_ID_MSB:PARA_CTU_ID_LSB];

assign O_EMPTY =
  (r_total_count == PARA_COUNT_WD'(0));

assign O_FULL =
  (r_total_count == PARA_COUNT_WD'(PARA_DEPTH));

assign O_COUNT = r_total_count;

endmodule: PARTITION_SYNTAX_FIFO
